<script setup lang="ts">
import {computed} from 'vue'
import {unlockResult} from '../unlock'
import {qualityGroups,latestServices,downloadEvidence,attemptObservedAt,latencyReadComplete,type QualityEvidence} from '../nodeQuality'
import {date,downloadSpeed,downloadTone,outcomeLabel,isReputationRule,type Attempt,type ServiceRule} from '../domain'
import {downloadGroup,servicePassed,serviceAvailability} from '../sharedResults'
import {attemptStatus,attemptTone,downloadConditionLabel} from '../measurementRounds'
const props=defineProps<{hideLatency?:boolean;evidence?:QualityEvidence;target:string;error?:string;catalog:ServiceRule[];expanded?:boolean;comparisonField?:'distribution'|'response'|'download'|'service'|'time'|'details';project?:'latency'|'download'|'service'|'combined';visibleServiceIds?:string[]}>()
const emit=defineEmits<{ 'select-service':[serviceId:string] }>()
const groups=computed(()=>props.evidence?qualityGroups(props.evidence.tests,props.evidence.monitor,props.target):[])
const current=computed(()=>groups.value[0]),downloads=computed(()=>downloadEvidence(props.evidence?.downloads||[]))
const download=computed(()=>downloads.value.latest),validDownload=computed(()=>downloads.value.valid),speed=computed(()=>downloadSpeed(validDownload.value))
const services=computed(()=>latestServices(props.evidence?.services||[]))
const visibleServices=computed(()=>props.visibleServiceIds===undefined?services.value:services.value.filter(a=>props.visibleServiceIds!.includes(a.service_id||a.rule.service_id||'')))
const serviceItems=computed(()=>visibleServices.value.slice(0,props.expanded||props.comparisonField==='service'?visibleServices.value.length:3))
const downloadTitle=computed(()=>[download.value?'最近检测：'+downloadConditionLabel(download.value):'',validDownload.value?'最近有效：'+downloadGroup(validDownload.value).label:''].filter(Boolean).join('\n'))
const readNames:Record<string,string>={latency:'延迟',monitor:'旧监测',download:'下载',service:'服务'}
const ms=(v:number|null|undefined)=>v===null||v===undefined?'—':Math.round(v)+' ms'
const title=computed(()=>current.value?`${current.value.source} · ${current.value.method} · ${current.value.target}\n条件：${current.value.condition}`:'无已保存样本')
const isSingle=computed(()=>!!props.project&&props.project!=='combined'&&!props.comparisonField)
const showLatency=computed(()=>!props.hideLatency&&(!props.project||props.project==='latency'||props.project==='combined')&&(!props.comparisonField||props.comparisonField==='distribution'||props.comparisonField==='response'))
const showDownload=computed(()=>(!props.project||props.project==='download'||props.project==='combined')&&(!props.comparisonField||props.comparisonField==='download'))
const showServices=computed(()=>(!props.project||props.project==='service'||props.project==='combined')&&(!props.comparisonField||props.comparisonField==='service'))
const rateTone=(rate:number|null|undefined,success:number)=>{if(rate===null||rate===undefined)return 'muted';if(success===0||rate===0)return 'bad';if(rate>=90)return 'good';if(rate>=50)return 'warn';return 'bad'}
const latencyTone=(val:number|null|undefined,success:number,rate?:number|null,source?:string)=>{if(success===0||val===null||val===undefined)return 'muted';if(rate!==null&&rate!==undefined&&rate<50)return 'bad';if(rate!==null&&rate!==undefined&&rate<80&&val<600)return 'warn';if(source==='monitor'){if(val<150)return 'good';if(val<300)return 'good';if(val<600)return 'warn';return 'bad'}if(val<600)return 'good';if(val<900)return 'warn';return 'bad'}
const speedTone=(v:number|null|undefined)=>{if(v===null||v===undefined)return 'muted';if(v>=10)return 'good';if(v>=2)return 'warn';return 'bad'}
const downloadStatusTone=(a?:any)=>{if(!a)return 'muted';const t=downloadTone(a);return t==='empty'?'muted':t}
const comparedService=(a:Attempt)=>props.comparisonField==='service'&&!['cancelled','interrupted','not_executed'].includes(a.execution_state)&&!isReputationRule({service_id:a.service_id||a.rule.service_id||''})?unlockResult(a):undefined
const serviceName=(a:Attempt)=>props.catalog.find(s=>s.service_id===(a.service_id||a.rule.service_id))?.name||a.rule.name||a.service_id||a.rule.service_id||'服务'
const serviceItemLabel=(a:Attempt)=>comparedService(a)?.label||(a.result?.outcome==='flapping'?(serviceAvailability(a)===0?'检测结论不一致':'未确认'):['matched','unlocked'].includes(a.result?.outcome||'')&&!servicePassed(a)?'未确认':a.result?.outcome==='not_executed'?'未执行':a.result?outcomeLabel(a.result.outcome):attemptStatus(a))
function comparisonReason(a:Attempt){
 const result=comparedService(a)
 if(!result||result.state!=='unknown')return ''
 if(a.result?.outcome==='reachable')return 'HTTP 可达（业务未验证）'
 if(result.reason&&result.reason!=='未取得明确结论')return result.reason
 const label=outcomeLabel(a.result?.outcome)
 return label===a.result?.outcome?'未取得明确结论':label
}
const serviceItemTone=(a?:Attempt)=>{const compared=a&&comparedService(a);if(compared)return compared.tone==='empty'?'muted':compared.tone;if(!a?.result)return 'muted';if(servicePassed(a))return 'good';if(serviceAvailability(a)===0)return 'bad';if(['flapping','matched','unlocked'].includes(a.result.outcome))return 'warn';const t=attemptTone(a);return t==='empty'?'muted':t}
</script>
<template><div class="quality-metrics" :class="{expanded,'comparison-field':comparisonField,'single-project':isSingle,['project-'+(comparisonField?'comparison':project||'combined')]:true}"><template v-if="comparisonField&&(!evidence||error)"><strong class="muted">{{error?'读取失败 · 不可比较':'读取保存记录…'}}</strong><small v-if="error">{{error}}</small></template><template v-else>
 <section v-if="showLatency" class="quality-latency" :title="title"><template v-if="error"><strong class="bad">读取失败</strong><small>{{error}}</small></template><template v-else-if="!evidence"><strong class="muted">读取保存记录…</strong></template><template v-else-if="!current||!current.total"><strong class="muted">未测</strong><small>{{current?.excluded?'仅取消 / 条件不足记录，未计入样本':'所选站点无历史样本'}}</small></template><template v-else><div class="quality-col quality-col-rate" v-if="!comparisonField||comparisonField==='response'"><div class="quality-pill-row"><span class="metric-caption">成功率</span><strong :class="rateTone(current.successRate,current.success)">响应成功 {{current.successRate===null?'—':current.successRate.toFixed(0)+'%'}}</strong><span v-if="current.success===0" class="badge bad">未获得响应</span><span v-else-if="current.successRate!==null&&current.successRate<50" class="badge bad">低响应率 · 纸面参考</span><span v-else-if="current.insufficient&&current.success>0" class="badge warn">样本偏少</span></div><span class="quality-secondary">{{current.success}} / {{current.total}} 样本</span></div><div class="quality-distribution"><div class="quality-col quality-col-p50" v-if="!comparisonField||comparisonField==='distribution'"><span class="metric-caption">中位</span><strong :class="latencyTone(current.p50,current.success,current.successRate,current.source)">P50 {{ms(current.p50)}}</strong></div><div class="quality-col quality-col-p95" v-if="!comparisonField||comparisonField==='distribution'"><span class="metric-caption">尾部</span><strong v-if="current.success>=20" :class="latencyTone(current.p95,current.success,current.successRate,current.source)">P95 {{ms(current.p95)}}</strong><span v-else class="muted">P95 样本不足</span></div></div><div class="quality-col quality-col-meta" v-if="!comparisonField"><small>{{date(current.lastAt)}} · {{current.source==='monitor'?'持续探测 (旧监测 RTT)':current.method==='http_get_via_proxy_first_byte'?'网页响应 (HTTP 首字节)':'方法 '+current.method}}<span v-if="groups.length>1"> · {{groups.length}} 组条件（显示最新组）</span></small><small v-if="current.insufficient&&current.comparable&&evidence&&latencyReadComplete(evidence,current)" class="warn">{{current.success?'样本较少 · 仅供参考，稳定性未确认':'未获得响应，暂无有效延迟'}}</small><small v-if="!current.comparable" class="warn">不可比较 · 出口条件证据不足</small></div></template><small v-if="evidence&&current&&!latencyReadComplete(evidence,current)" class="warn">{{current.source==='monitor'?'旧监测':'延迟'}}读取不完整 · 不可比较</small><small v-if="evidence&&!current&&(!evidence.reads.latency.complete||!evidence.reads.monitor.complete)" class="warn">延迟/监测记录读取不完整 · 未测状态未确认</small></section>
 <section v-if="showDownload" class="quality-download" :title="downloadTitle"><div class="quality-col quality-col-status"><strong>最近检测：<span class="badge" :class="downloadStatusTone(download)">{{download?attemptStatus(download,true):'未测'}}</span></strong></div><div class="quality-col quality-col-speed"><template v-if="validDownload"><strong>{{validDownload.attempt_id===download?.attempt_id?'最近有效速度':'历史有效速度'}}：<span class="badge" :class="speedTone(speed)">{{speed!.toFixed(2)}} MiB/s</span></strong><span class="quality-secondary">{{validDownload.rule.mode==='adaptive'?(downloadGroup(validDownload).kind==='full'?'稳定速度':'未稳定均速'):downloadGroup(validDownload).kind==='partial'?'限时部分 (有效部分)':'完整读取'}} · {{date(attemptObservedAt(validDownload))}}</span></template><small v-else class="muted">{{download?'本次未取得有效速度':'尚无测速记录'}}</small></div><div class="quality-col quality-col-meta"><small v-if="download">{{date(attemptObservedAt(download))}} · {{download.rule.method||'方法未知'}} / v{{download.rule.rule_version??'?'}}</small><small v-if="evidence&&!evidence.reads.download.complete" class="warn">下载读取不完整 · 最近状态/速度未确认{{comparisonField?' · 不可比较':''}}</small><details v-if="comparisonField&&download" class="comparison-conditions"><summary>检测条件与速度依据</summary><p>最近检测：{{downloadConditionLabel(download)}}</p><p v-if="validDownload">{{validDownload.attempt_id===download?.attempt_id?'速度条件':'历史速度条件'}}：{{downloadGroup(validDownload).label}}</p></details></div></section>
 <section v-if="showServices" class="quality-services"><div v-if="!comparisonField||visibleServiceIds===undefined" class="quality-services-header"><strong>服务检测 {{visibleServices.length?'（最近有记录 '+visibleServices.length+' 项）':'：未测'}}</strong></div><strong v-if="comparisonField&&visibleServiceIds&&!serviceItems.length" class="muted">未测</strong><div class="quality-services-list"><small v-for="a in serviceItems" :key="a.service_id||a.rule.service_id" class="service-pill-item" role="button" tabindex="0" :aria-label="'查看 '+serviceName(a)+' 保存证据：'+serviceItemLabel(a)" :title="comparedService(a)?.reason" @click="emit('select-service',a.service_id||a.rule.service_id||'')" @keydown.enter.prevent="emit('select-service',a.service_id||a.rule.service_id||'')" @keydown.space.prevent="emit('select-service',a.service_id||a.rule.service_id||'')"><span v-if="!comparisonField||visibleServiceIds===undefined" class="service-item-label">{{catalog.find(s=>s.service_id===(a.service_id||a.rule.service_id))?.name||a.service_id||a.rule.service_id}}：</span><strong :class="serviceItemTone(a)">{{serviceItemLabel(a)}}</strong><span v-if="comparisonReason(a)" class="service-item-reason">{{comparisonReason(a)}}</span><time class="service-item-time">{{date(attemptObservedAt(a))}}</time></small></div><small v-if="evidence&&!evidence.reads.service.complete" class="warn">服务读取不完整 · 最近结论未确认{{comparisonField?' · 不可比较':''}}</small></section>
 <section v-if="comparisonField==='time'" class="quality-times"><small v-if="!project||project==='combined'||project==='latency'">延迟：<time v-if="current" :datetime="current.lastAt">{{date(current.lastAt)}}</time><span v-else>未测</span></small><small v-if="!project||project==='combined'||project==='download'">下载：<time v-if="download" :datetime="attemptObservedAt(download)">{{date(attemptObservedAt(download))}}</time><span v-else>未测</span></small><small v-if="(!project||project==='combined'||project==='download')&&validDownload&&validDownload.attempt_id!==download?.attempt_id">历史有效：<time :datetime="attemptObservedAt(validDownload)">{{date(attemptObservedAt(validDownload))}}</time></small><template v-if="(!project||project==='combined'||project==='service')&&(!visibleServiceIds||visibleServiceIds.length)"><small v-for="a in visibleServices" :key="a.service_id||a.rule.service_id">{{catalog.find(s=>s.service_id===(a.service_id||a.rule.service_id))?.name||a.service_id||a.rule.service_id}}：<time :datetime="attemptObservedAt(a)">{{date(attemptObservedAt(a))}}</time></small><small v-if="!visibleServices.length">服务：未测</small></template></section>
 <details v-if="(expanded||comparisonField==='details')&&(!comparisonField||comparisonField==='details')&&evidence" class="quality-evidence-details"><summary>分组依据、样本与边界</summary><p>固定窗口 {{date(evidence.since)}} — {{date(evidence.until)}}；{{evidence.complete?'已读完窗口内保存记录':'读取不完整'}}。响应成功率不代表业务可用。P95 至少 20 个成功样本才在列表展示；5 个以下成功样本标为样本不足。波动为成功时延的总体标准差。</p><p v-for="(status,kind) in evidence.reads" :key="kind">{{readNames[kind]}}历史：{{status.complete?'读取完整':'读取不完整'}}{{status.error?' · '+status.error:''}}</p><article v-for="g in groups" :key="g.key"><strong>{{g.source}} · {{g.method}}</strong><p>{{g.target}} · {{g.success}}/{{g.total}} · P50 {{ms(g.p50)}} · P95 描述值 {{ms(g.p95)}} · 波动 {{ms(g.jitter)}} · 排除取消/未执行 {{g.excluded}}</p><p>{{g.comparable?'方法与路径有记录；仅同条件组可比较':'不可比较：旧方法或路径条件缺失'}} · {{g.condition}}</p></article><p v-if="download">最近检测条件：{{downloadConditionLabel(download)}}</p><p v-if="validDownload">最近有效速度条件：{{downloadGroup(validDownload).label}}</p><p>没有综合评分；不同目标、来源、协议、方法、版本和出口条件不合并。节点地区取自名称/配置，不等于出口地区。</p></details>
</template></div></template>

<style scoped>
.quality-metrics.comparison-field{display:block;min-width:0}
.comparison-field .quality-latency,.comparison-field .quality-download{display:flex;flex-direction:column;gap:8px}
.quality-metrics.comparison-field .quality-distribution{display:flex;flex-wrap:wrap;gap:12px 8px}
.comparison-field .quality-col{display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-width:0}
.comparison-field .quality-col-p95{display:flex}
.quality-metrics.comparison-field .badge.warn{display:inline-flex;margin:0}
.comparison-field .quality-services{display:block}
.comparison-field .quality-col-rate{gap:5px}
.comparison-field .quality-pill-row{display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.comparison-field .quality-pill-row .metric-caption{display:none}
.comparison-field .quality-secondary,.comparison-field .quality-col-meta{color:var(--hd-muted);font-size:11px}
.comparison-field .quality-col-p50 strong,.comparison-field .quality-col-p95 strong{font-size:15px;font-variant-numeric:tabular-nums}
.comparison-conditions{font-size:11px;line-height:1.6;overflow-wrap:anywhere}
.comparison-conditions summary{cursor:pointer;color:var(--hd-accent)}
.comparison-conditions p{margin:6px 0 0}
.comparison-field .quality-services-list{display:flex;flex-direction:column;align-items:stretch}
.comparison-field .service-pill-item{display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:4px 0;cursor:pointer;background:none;border:0}
.comparison-field .service-pill-item strong{white-space:normal;overflow-wrap:anywhere;max-width:100%;box-sizing:border-box}
.comparison-field .service-pill-item:hover strong{text-decoration:underline;text-underline-offset:3px}
.comparison-field .service-pill-item:focus-visible{outline:2px solid var(--hd-accent);outline-offset:3px}
.comparison-field .service-item-reason{color:var(--hd-muted);font-size:11px;line-height:1.5}
.comparison-field .service-item-time{color:var(--hd-muted);font-size:11px}
.comparison-field .quality-times{display:flex;flex-direction:column;gap:4px;color:var(--hd-muted)}
.comparison-field .quality-evidence-details{font-size:11px;line-height:1.6;overflow-wrap:anywhere}
.comparison-field .quality-evidence-details summary{cursor:pointer;color:var(--hd-accent)}
.comparison-field .quality-evidence-details article{border-top:1px solid var(--hd-line);margin-top:8px;padding-top:8px}
</style>
